INSERT INTO ai_knowledge (source_type, source_id, title, content, embedding_json, embedding_model, token_count, enabled) SELECT 2, NULL, '如何上架二手商品', '进入二手市场页面，点击右上角"发布商品"按钮，填写商品标题、描述、价格并上传至少一张实物照片，选择商品分类后提交。商品提交后即可在二手市场列表展示，其他同学看到后可以通过私信联系你。交易完成后请及时在"我的-我的发布"中将商品下架，避免重复打扰。', NULL, 'local-ngram-256', LENGTH('进入二手市场页面，点击右上角"发布商品"按钮，填写商品标题、描述、价格并上传至少一张实物照片，选择商品分类后提交。商品提交后即可在二手市场列表展示，其他同学看到后可以通过私信联系你。交易完成后请及时在"我的-我的发布"中将商品下架，避免重复打扰。'), 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ai_knowledge WHERE title='如何上架二手商品');
INSERT INTO ai_knowledge (source_type, source_id, title, content, embedding_json, embedding_model, token_count, enabled) SELECT 2, NULL, '如何参与校园活动', '进入校园活动页面浏览正在报名的活动，点击感兴趣的活动查看详情，点击右下角"立即报名"按钮即可完成报名。报名成功后如需联系活动主办方，可在活动详情页查看发起人信息，通过平台私信功能与发起人沟通，询问活动地点、时间安排等具体事项。活动开始前主办方也会通过平台消息通知已报名的同学。', NULL, 'local-ngram-256', LENGTH('进入校园活动页面浏览正在报名的活动，点击感兴趣的活动查看详情，点击右下角"立即报名"按钮即可完成报名。报名成功后如需联系活动主办方，可在活动详情页查看发起人信息，通过平台私信功能与发起人沟通，询问活动地点、时间安排等具体事项。活动开始前主办方也会通过平台消息通知已报名的同学。'), 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ai_knowledge WHERE title='如何参与校园活动');
INSERT INTO ai_knowledge (source_type, source_id, title, content, embedding_json, embedding_model, token_count, enabled) SELECT 2, NULL, '快递代取怎么收费', '快递代取服务费用由接单同学自行定价，一般在2元到5元之间，根据快递大小和重量略有不同，部分订单会有小费加成，新用户首单立减5元。下单后可以在订单大厅等待同学接单，接单后可在订单详情查看实时状态。', NULL, 'local-ngram-256', LENGTH('快递代取服务费用由接单同学自行定价，一般在2元到5元之间，根据快递大小和重量略有不同，部分订单会有小费加成，新用户首单立减5元。下单后可以在订单大厅等待同学接单，接单后可在订单详情查看实时状态。'), 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ai_knowledge WHERE title='快递代取怎么收费');
INSERT INTO ai_knowledge (source_type, source_id, title, content, embedding_json, embedding_model, token_count, enabled) SELECT 2, NULL, '如何发布跑腿订单', '进入校园跑腿页面，选择"发布跑腿"，填写需要代办的事项（如代买午饭、代取快递）、取货地址、送达地址和期望时间段，设置合理的服务费后提交。跑腿同学接单后会与你联系，完成后订单自动结算。', NULL, 'local-ngram-256', LENGTH('进入校园跑腿页面，选择"发布跑腿"，填写需要代办的事项（如代买午饭、代取快递）、取货地址、送达地址和期望时间段，设置合理的服务费后提交。跑腿同学接单后会与你联系，完成后订单自动结算。'), 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ai_knowledge WHERE title='如何发布跑腿订单');
INSERT INTO ai_knowledge (source_type, source_id, title, content, embedding_json, embedding_model, token_count, enabled) SELECT 2, NULL, '打印服务怎么用', '进入打印服务页面，上传需要打印的文件（支持PDF、Word、Excel、PPT格式），选择纸张大小（A4等）、打印份数、是否双面、是否彩印，系统自动计算费用，填写收货地址和联系电话后提交订单。打印完成后会配送到你填写的地址。', NULL, 'local-ngram-256', LENGTH('进入打印服务页面，上传需要打印的文件（支持PDF、Word、Excel、PPT格式），选择纸张大小（A4等）、打印份数、是否双面、是否彩印，系统自动计算费用，填写收货地址和联系电话后提交订单。打印完成后会配送到你填写的地址。'), 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ai_knowledge WHERE title='打印服务怎么用');
INSERT INTO ai_knowledge (source_type, source_id, title, content, embedding_json, embedding_model, token_count, enabled) SELECT 2, NULL, '如何找到失物或招领', '进入失物招领页面，可以切换"寻物启事"和"失物招领"两个标签。丢失物品的同学发布寻物启事，捡到物品的同学发布招领信息，附上物品照片和捡到地点。看到匹配的信息可以通过发布者的联系方式或平台私信联系对方。', NULL, 'local-ngram-256', LENGTH('进入失物招领页面，可以切换"寻物启事"和"失物招领"两个标签。丢失物品的同学发布寻物启事，捡到物品的同学发布招领信息，附上物品照片和捡到地点。看到匹配的信息可以通过发布者的联系方式或平台私信联系对方。'), 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ai_knowledge WHERE title='如何找到失物或招领');
INSERT INTO ai_knowledge (source_type, source_id, title, content, embedding_json, embedding_model, token_count, enabled) SELECT 2, NULL, '游戏搭子怎么找', '进入游戏搭子页面，选择你玩的游戏分类（如LOL、CSGO等），浏览其他同学发布的找搭子信息，包含游戏段位和在线时间，看到合适的可以点击"联系TA"私信约时间。也可以自己发布找搭子信息。', NULL, 'local-ngram-256', LENGTH('进入游戏搭子页面，选择你玩的游戏分类（如LOL、CSGO等），浏览其他同学发布的找搭子信息，包含游戏段位和在线时间，看到合适的可以点击"联系TA"私信约时间。也可以自己发布找搭子信息。'), 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ai_knowledge WHERE title='游戏搭子怎么找');
INSERT INTO ai_knowledge (source_type, source_id, title, content, embedding_json, embedding_model, token_count, enabled) SELECT 2, NULL, '如何切换学校', '进入"我的"页面，点击头像上方的学校名称，进入学校选择页面，列表中选择你所在的学校即可切换。切换后首页的公告、二手商品、跑腿订单等内容都会切换为对应学校的数据，不同学校的数据相互隔离。', NULL, 'local-ngram-256', LENGTH('进入"我的"页面，点击头像上方的学校名称，进入学校选择页面，列表中选择你所在的学校即可切换。切换后首页的公告、二手商品、跑腿订单等内容都会切换为对应学校的数据，不同学校的数据相互隔离。'), 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ai_knowledge WHERE title='如何切换学校');
INSERT INTO ai_knowledge (source_type, source_id, title, content, embedding_json, embedding_model, token_count, enabled) SELECT 2, NULL, '平台如何保证交易安全', '平台所有交易均由同学之间自行协商完成，建议本校面交、当面验货。平台对发布内容有审核机制，禁止发布违禁物品。如遇纠纷或违规行为，可以通过"我的-意见反馈"举报，管理员会及时处理违规账号。', NULL, 'local-ngram-256', LENGTH('平台所有交易均由同学之间自行协商完成，建议本校面交、当面验货。平台对发布内容有审核机制，禁止发布违禁物品。如遇纠纷或违规行为，可以通过"我的-意见反馈"举报，管理员会及时处理违规账号。'), 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ai_knowledge WHERE title='平台如何保证交易安全');
INSERT INTO ai_knowledge (source_type, source_id, title, content, embedding_json, embedding_model, token_count, enabled) SELECT 2, NULL, 'AI助手能回答什么问题', '我可以回答校园公告、业务规则类的问题，比如快递怎么取、打印怎么收费、怎么上架二手商品、如何参与活动等。我的回答都基于平台内已有的公告和资料，如果问题超出了资料范围，我会明确告知，建议你咨询学校相关部门。', NULL, 'local-ngram-256', LENGTH('我可以回答校园公告、业务规则类的问题，比如快递怎么取、打印怎么收费、怎么上架二手商品、如何参与活动等。我的回答都基于平台内已有的公告和资料，如果问题超出了资料范围，我会明确告知，建议你咨询学校相关部门。'), 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ai_knowledge WHERE title='AI助手能回答什么问题');